"use client"

import * as React from "react"
import { Progress as ProgressPrimitive } from "@base-ui/react/progress"

import { cn } from "@/lib/utils"

/*
 * Progress — a recessed steel channel (inset shadow) with a glossy azure alloy
 * fill that reads as the same metal as the primary button / active toggle.
 */

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Progress = React.forwardRef<
  HTMLDivElement,
  Omit<WithClassName<ProgressPrimitive.Root.Props>, "value"> & {
    value?: ProgressPrimitive.Root.Props["value"]
  }
>(({ className, value, ...props }, ref) => (
  <ProgressPrimitive.Root
    ref={ref}
    value={value ?? null}
    className={cn(
      "relative h-2 w-full overflow-hidden rounded-full border border-white/10",
      "bg-input [box-shadow:var(--shadow-inset)]",
      className
    )}
    {...props}
  >
    <ProgressPrimitive.Track className="h-full w-full">
      <ProgressPrimitive.Indicator className="h-full w-full flex-1 rounded-full [background:var(--surface-on)] [box-shadow:var(--shadow-primary)] transition-all duration-slow" />
    </ProgressPrimitive.Track>
  </ProgressPrimitive.Root>
))
Progress.displayName = "Progress"

export { Progress }
